def pinverse(inp, rcond=1e-15):
    """Compute the Moore-Penrose pseudoinverse of a matrix or matrix batch."""
    logger.debug("GEMS PINVERSE")

    if inp.ndim < 2:
        raise RuntimeError("pinverse: expected a tensor with at least 2 dimensions")
    if inp.device.type != device.name or inp.dtype != torch.float32:
        raise NotImplementedError(
            f"FlagGems pinverse currently supports only float32 {device.name} tensors"
        )
    if inp.requires_grad:
        raise NotImplementedError(
            "FlagGems pinverse does not yet support autograd inputs"
        )
    if rcond < 0.0:
        raise NotImplementedError(
            "FlagGems pinverse does not yet support negative rcond values"
        )

    m, n = inp.shape[-2:]
    if inp.numel() == 0:
        return torch.empty((*inp.shape[:-2], n, m), dtype=inp.dtype, device=inp.device)

    if not inp.is_contiguous():
        inp = contiguous(inp)

    result = svd(inp, some=True, compute_uv=True)

    k = min(m, n)
    batch = inp.numel() // (m * n)
    u = result.U.reshape(batch, m, k)
    s = result.S.reshape(batch, k)
    v = result.V.reshape(batch, n, k)
    output = torch.empty((batch, n, m), dtype=inp.dtype, device=inp.device)

    block_m = 16 if m <= 16 else 32
    block_n = 16 if n <= 16 else 32
    # gcu400: BLOCK_K must cover K in one unrolled step when possible so the
    # static K loop stays at a single iteration; larger K unrolls in steps of
    # 128 (svd supports min(m, n) <= 1024, i.e. at most 8 unrolled steps).
    if k <= 64:
        block_k = max(16, triton.next_power_of_2(k))
    else:
        block_k = 128
    tiles_per_batch = triton.cdiv(m, block_m) * triton.cdiv(n, block_n)
    total_work = tiles_per_batch * batch
    grid = (min(total_work, _GRID_X_LIMIT),)
