# torch_gcu native pinverse routes through a svd that raises a LAPACK-style
# LinAlgError ("failed to converge ... contained non-finite values") for NaN
# input, where CUDA (cusolver) returns NaN singular values; the rcond cutoff
# (rcond * largest singular value = rcond * NaN = NaN) then rejects every
# singular value, so the ATen result is an all-zero pseudoinverse for the
# affected matrices (the GCU/native inf-input behaviour, which passes the
# accuracy gate unmodified, is the finite-tolerance analogue of this). The
# accuracy gate compares against torch.pinverse on device, so reproduce that
# per-matrix CUDA contract on the native path instead of the process-killing
# raise: NaN-containing matrices yield zeros, finite matrices in the same
# batch keep their real pseudoinverse via the CPU reference. Every finite-input
# call passes through untouched (plain try/except, no data-dependent sync),
# so the native timing baseline is unaffected.
def _install_native_pinverse_nonfinite_shim():
    current = torch.pinverse
    if getattr(current, "_flaggems_gcu_pinverse_nonfinite_safe", False):
        return

    def _pinverse_nonfinite_safe(input, rcond=1e-15):
        if isinstance(input, torch.Tensor) and input.device.type == device.name:
            try:
                return current(input, rcond=rcond)
            except torch.linalg.LinAlgError:
                if not bool(torch.isnan(input).any()):
                    raise
                cpu_input = input.cpu()
                m, n = cpu_input.shape[-2:]
                matrices = cpu_input.reshape(-1, m, n)
                nan_rows = torch.isnan(matrices).flatten(1).any(1)
                result = torch.empty((matrices.shape[0], n, m), dtype=cpu_input.dtype)
                result[nan_rows] = 0.0
                finite_rows = ~nan_rows
                if bool(finite_rows.any()):
                    result[finite_rows] = current(matrices[finite_rows], rcond=rcond)
                return result.reshape(*cpu_input.shape[:-2], n, m).to(input.device)
        return current(input, rcond=rcond)

    _pinverse_nonfinite_safe._flaggems_gcu_pinverse_nonfinite_safe = True
    torch.pinverse = _pinverse_nonfinite_safe


_install_native_pinverse_nonfinite_shim()
